from app.database import db

class Note(db.Model):
    __tablename__ = 'notes'

    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.Text, nullable=False)

    def __init__(self, content):
        self.content = content

    def __repr__(self):
        return f'<Note {self.id}>'

from flask import Blueprint, render_template, request, redirect, url_for
from app.models.note import Note
from app.database import db

notes_bp = Blueprint('notes', __name__)

@notes_bp.route('/')
def index():
    # Fetch all notes from the database
    notes = Note.query.all()
    return render_template('index.html', notes=notes)

@notes_bp.route('/add', methods=['POST'])
def add_note():
    # Get the note text from the form
    note_text = request.form.get('note_text')

    if note_text:
        # Create a new Note object and save it to the database
        new_note = Note(content=note_text)
        db.session.add(new_note)
        db.session.commit()

    return redirect(url_for('notes.index'))

@notes_bp.route('/delete/<int:note_id>', methods=['POST'])
def delete_note(note_id):
    # Find the note by ID and delete it from the database
    note_to_delete = Note.query.get(note_id)

    if note_to_delete:
        db.session.delete(note_to_delete)
        db.session.commit()

    return redirect(url_for('notes.index'))

/* static/styles.css */
/* CSS for styling the note-taking interface */

/* Global styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f9f9f9;
    color: #333;
}

/* Container for the app */
.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
    background-color: #ffffff;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    border-radius: 8px;
}

/* Header styles */
header {
    text-align: center;
    margin-bottom: 20px;
}

header h1 {
    font-size: 24px;
    color: #2c3e50;
}

/* Input form styles */
.note-form {
    margin-bottom: 20px;
}

.note-form input[type="text"],
.note-form textarea {
    width: 100%;
    padding: 10px;
    margin: 10px 0;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 16px;
}

.note-form textarea {
    resize: vertical;
}

.note-form button {
    display: inline-block;
    padding: 10px 20px;
    background-color: #3498db;
    color: #ffffff;
    border: none;
    border-radius: 4px;
    font-size: 16px;
    cursor: pointer;
}

.note-form button:hover {
    background-color: #2980b9;
}

/* Notes list styles */
.notes {
    list-style-type: none;
    padding: 0;
    margin: 0;
}

.notes li {
    padding: 15px;
    margin-bottom: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
    background-color: #f4f4f4;
}

.notes li h2 {
    margin: 0 0 10px;
    font-size: 18px;
    color: #2c3e50;
}

.notes li p {
    margin: 0;
    font-size: 14px;
    color: #555;
}

/* Footer styles */
footer {
    text-align: center;
    margin-top: 20px;
    color: #aaa;
    font-size: 14px;
}

footer a {
    color: #3498db;
    text-decoration: none;
}

footer a:hover {
    text-decoration: underline;
}
